package net.officefloor.hq.app.sheet;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    public record SheetView(String id, LocalDate today, boolean archived, Long lastBatch) {
        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.isArchived(), sheet.getLastBatchNumber());
        }
    }

    /** The figures of a sheet's descendants added up, each as that sheet shows it, and the sheet's own
     *  figures: as they are now, or as they stood at the end of the screen's as-of date. Per grade, the
     *  descendants' due-totals of the people on it not retired; per status, their claims with it. */
    public record DescendantFigures(int sheets, int people, String dueTotal, String overdueTotal, int ownPeople,
            String ownDueTotal, String ownOverdueTotal, Map<String, String> gradeDueTotals,
            Map<String, Integer> statusCounts, List<PersonFiguresView> personFigures) {
    }

    /** A descendant's person as that sheet shows them: their name and aliases, their due-total (null
     *  when they have none) and their overdue-total. */
    public record PersonFiguresView(String name, List<String> aliases, String dueTotal, String overdueTotal) {
    }

    public record TodayRequest(@NotNull LocalDate today) {
    }

    public record CloneRequest(String to) {
    }

    /** The sheet a clone was made to. */
    public record CloneView(String to) {
    }

    private final SheetService service;
    private final RollupService rollups;
    private final PeriodService periods;
    private final SettingService settings;
    private final ClaimService claims;
    private final SheetCloneService clones;

    public SheetController(SheetService service, RollupService rollups, PeriodService periods, SettingService settings,
            ClaimService claims, SheetCloneService clones) {
        this.service = service;
        this.clones = clones;
        this.claims = claims;
        this.rollups = rollups;
        this.periods = periods;
        this.settings = settings;
    }

    /** Load a sheet by id, starting it empty if it was never loaded before. */
    @PostMapping("/{id}/load")
    public SheetView load(@PathVariable @NotBlank @Size(max = 200) String id) {
        return SheetView.of(service.load(id.trim()));
    }

    /** The sheet's descendants' figures added up: how many people are on them, and each one's
     *  due-total and overdue-total as that sheet shows it. The sheet's own figures are given apart.
     *  While the screen is set to an as-of date, every sheet's figures are as it stood at the end of
     *  that day, the date standing in for the sheet's today. */
    @GetMapping("/{id}/descendant-figures")
    public DescendantFigures descendantFigures(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOfHeader) {
        LocalDate asOf = AsOf.parse(asOfHeader);
        int people = 0;
        BigDecimal due = BigDecimal.ZERO.setScale(2);
        BigDecimal overdue = BigDecimal.ZERO.setScale(2);
        Map<String, BigDecimal> gradeDues = new TreeMap<>();
        Map<String, Integer> statusCounts = new TreeMap<>();
        List<PersonFiguresView> personFigures = new ArrayList<>();
        var descendants = service.descendants(id.trim());
        for (String sheet : descendants) {
            rollups.personFigures(sheet, asOf).forEach(p -> personFigures.add(new PersonFiguresView(p.name(),
                    p.aliases(), p.dueTotal() == null ? null : p.dueTotal().toPlainString(),
                    p.overdueTotal().toPlainString())));
            RollupService.Headline figures = rollups.headline(sheet, asOf);
            people += figures.people();
            due = due.add(figures.dueTotal());
            overdue = overdue.add(figures.overdueTotal());
            RollupService.Breakdown breakdown = rollups.breakdown(sheet, asOf);
            breakdown.gradeDueTotals().forEach((grade, total) -> gradeDues.merge(grade, total, BigDecimal::add));
            breakdown.statusCounts().forEach((status, count) -> statusCounts.merge(status, count, Integer::sum));
        }
        Map<String, String> gradeDueTotals = new TreeMap<>();
        gradeDues.forEach((grade, total) -> gradeDueTotals.put(grade, total.toPlainString()));
        RollupService.Headline own = rollups.headline(id.trim(), asOf);
        return new DescendantFigures(descendants.size(), people, due.toPlainString(), overdue.toPlainString(),
                own.people(), own.dueTotal().toPlainString(), own.overdueTotal().toPlainString(), gradeDueTotals,
                statusCounts, personFigures);
    }

    /** Change the sheet's today, closing the periods past their grace days and releasing every claim
     *  editor's lock when the date moved; the audit records each person's due-total on the day being
     *  left when the date moved, then only the figures it moved. */
    @PutMapping("/{id}/today")
    public SheetView setToday(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated TodayRequest request) {
        String sheet = id.trim();
        String by = SignedInUser.decode(user);
        return SheetView.of(rollups.track(sheet, by,
                () -> {
                    LocalDate was = service.today(sheet);
                    if (!was.equals(request.today())) {
                        rollups.snapshot(sheet, by, request.today());
                    }
                    Sheet changed = service.setToday(sheet, request.today());
                    if (!was.equals(changed.getToday())) {
                        claims.releaseLocks(sheet);
                    }
                    periods.autoClose(sheet, by);
                    return changed;
                }));
    }

    /** Archive the sheet: only a steward may, and only once; from then on every change is refused. */
    @PostMapping("/{id}/archive")
    public SheetView archive(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user) {
        String sheet = id.trim();
        String by = SignedInUser.decode(user);
        if (settings.roleOf(sheet, by) != Role.STEWARD) {
            throw new ArchiveRefusedException("only a steward may archive the sheet");
        }
        return SheetView.of(service.archive(sheet, by));
    }

    /** Clone the sheet to another id never used: only a steward may. */
    @PostMapping("/{id}/clone")
    public CloneView cloneTo(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody CloneRequest request) {
        String to = request.to() == null ? "" : request.to().trim();
        clones.cloneTo(id.trim(), SignedInUser.decode(user), to);
        return new CloneView(to);
    }

    /** A date that is not a real yyyy-mm-dd date is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }
}
     *  sheet's today (null: as it shows them now). */
    @Transactional(readOnly = true)
    public Headline headline(String sheetId, LocalDate asOf) {
        Rollup rollup = rollup(sheetId, asOf);
        return new Headline(rollup.people().size(), rollup.dueTotal(), rollup.overdueTotal());
    }

    /** A person's figures on a sheet as it shows them: their name and aliases, their due-total (null
     *  when they have none) and their overdue-total. */
    public record PersonFigures(String name, List<String> aliases, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }

    /** Each person's figures on the sheet as it stood at the end of a day, that day standing in for
     *  the sheet's today (null: as it shows them now), in list order. */
    @Transactional(readOnly = true)
    public List<PersonFigures> personFigures(String sheetId, LocalDate asOf) {
        Rollup rollup = rollup(sheetId, asOf);
        Map<Long, List<String>> aliases = personService.aliases(sheetId, asOf);
        List<PersonFigures> list = new ArrayList<>();
        rollup.people().forEach((personId, f) -> list.add(new PersonFigures(f.name(),
                aliases.getOrDefault(personId, List.of()), f.due(), f.overdue())));
        return list;
    }

    /** A sheet's figures broken down: per grade, the due-totals of the people on it who are not
     *  retired added up (skipping those with no figure); per status, how many of its claims have it. */
    public record Breakdown(Map<String, BigDecimal> gradeDueTotals, Map<String, Integer> statusCounts) {
    }

    /** The sheet's figures broken down as it stood at the end of a day, that day standing in for the
     *  sheet's today (null: as it shows them now). */
    @Transactional(readOnly = true)
    public Breakdown breakdown(String sheetId, LocalDate asOf) {
        LocalDate today = asOf != null ? asOf : sheets.today(sheetId);
        Rollup rollup = rollup(sheetId, asOf);
        Map<String, BigDecimal> gradeDues = new LinkedHashMap<>();
        for (Person person : personService.list(sheetId, asOf)) {
            Figures f = rollup.people().get(person.getId());
            String grade = grades.gradeOn(person.getId(), today, asOf);
            if (person.isRetired() || f == null || grade == null) {
                continue;
            }
            gradeDues.merge(grade, f.due() == null ? NONE : f.due(), BigDecimal::add);
        }
        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDesc(sheetId);
        Map<String, Integer> statusCounts = new LinkedHashMap<>();
        (asOf == null ? sheetClaims : history.claims(sheetClaims, asOf))
                .forEach(claim -> statusCounts.merge(claim.getStatus().name(), 1, Integer::sum));
        return new Breakdown(gradeDues, statusCounts);
    }

    /** Each person's due-total on the sheet as it shows it now ("n/a" for none), by person id in list order. */
    @Transactional(readOnly = true)
    public Map<Long, String> dueTotals(String sheetId) {
        Map<Long, String> dues = new LinkedHashMap<>();
        rollup(sheetId).people().forEach((personId, figures) -> dues.put(personId, text(figures.due())));
        return dues;
    }

    /** Record in the audit each person's due-total as it stands now, in list order: the figures of
     *  the day the sheet's today is about to leave; each is kept for the person with that day and the
     *  day the sheet's today is moving to. While the score log is on, each person's score then is
     *  recorded first, in list order. */
    public void snapshot(String sheetId, String user, LocalDate movingTo) {
        LocalDate leaving = sheets.today(sheetId);
        Rollup rollup = rollup(sheetId);
        if (settings.scoreLog(sheetId)) {
            rollup.people().values().forEach(figures -> audit.recordOnCommit("SCORE sheet=" + sheetId + " by=" + user
                    + " name=" + figures.name() + " score=" + score(figures).toPlainString()));
        }
        rollup.people().forEach((personId, figures) -> {
            personService.snapshot(sheetId, personId, leaving, text(figures.due()), movingTo);
            audit.recordOnCommit("SNAPSHOT sheet=" + sheetId + " by=" + user + " name=" + figures.name()
                    + " due-total=" + text(figures.due()));
        });
    }

    /** A person's score: their settled figures (corrections left out) divided by 100, minus 5 for each overdue claim of theirs
     *  that counts, rounded half to even to a whole number. */
    private static BigDecimal score(Figures figures) {
        BigDecimal score = figures.settled().movePointLeft(2).subtract(BigDecimal.valueOf(5L * figures.overdueCount()))
                .setScale(0, RoundingMode.HALF_EVEN);
        return score.signum() == 0 ? BigDecimal.ZERO : score;
    }

    private Rollup rollup(String sheetId) {
        return rollup(sheetId, null);
    }

    /** The sheet's figures as it stood at the end of a day: its people, claims, holds, grades, rates
     *  and settings as they stood then, the day standing in for the sheet's today (null: now). */
    if (!current) {
      const list = await firstValueFrom(
        this.http.get<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
      ).catch(() => []);
      current = list.find((p) => p.id === id) ?? null;
    }
    if (!current || this.session.sheetId() !== sheet) return;
    const now = current;
    this.people.update((list) => list.map((p) => (p.id === now.id ? now : p)));
    if (this.editingId() === now.id) {
      this.editingVersion.set(now.version);
      this.name.set(now.name);
      this.grade.set(this.gradeOf(now));
    }
  }

  /** Read the sheet's people and claims; a response for an earlier load is dropped. */
  private async read(sheet: string, load: number): Promise<void> {
    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
    const [list, claims, tags, descendants] = await Promise.all([
      firstValueFrom(this.http.get<Person[]>(`${base}/people`)),
      firstValueFrom(this.http.get<Claim[]>(`${base}/claims`)),
      firstValueFrom(this.http.get<string[]>(`${base}/claim-tags`)),
      firstValueFrom(this.http.get<DescendantFigures>(`${base}/descendant-figures`)),
    ]);
    if (this.session.loads() !== load) return;
    this.people.set(list);
    this.claims.set(claims);
    this.usedTags.set(tags);
    this.descendantFigures.set(descendants);
  }
}

